//! The Export tab's "run it in Ollama / LM Studio" buttons: `export-ollama` and
//! `export-lmstudio` with the same code (`slm_cli::runtime_export`): the tool is found by
//! the `bin` field, then `FERRUM_OLLAMA` / `FERRUM_LMS`, then `PATH`, then the default install
//! location; the Modelfile is generated by the CLI's function; anything but a Ferrum `gpt2`
//! GGUF is refused before any tool starts (a llama GGUF with the Manual 9.5 pointer).
//!
//! Nothing here starts a tool except [`export_to_runtime`] with a run requested.
//! [`preview_runtime_export`] only reads the model header and looks the tool up, and the
//! "write the Modelfile only" mode starts nothing at all.

use crate::jobs::Job;
use crate::paths::checked_path;
use crate::AppState;
use serde::{Deserialize, Serialize};
use slm_cli::runtime_export as rx;
use std::path::Path;
use tauri::State;

#[derive(Deserialize, Serialize, Clone, Copy, Debug, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Target {
    Ollama,
    Lmstudio,
}

#[derive(Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct RuntimeParams {
    /// A Ferrum `gpt2` GGUF.
    pub model_path: String,
    pub target: Target,
    /// Ollama: the model name for `ollama create`.
    #[serde(default)]
    pub name: String,
    /// LM Studio: `publisher/name`; empty means `ferrum/<file stem>`.
    #[serde(default)]
    pub repo: String,
    /// Path of the `ollama` / `lms` binary; empty means look it up.
    #[serde(default)]
    pub bin: String,
    /// Ollama only: write the Modelfile here and stop (the CLI's `--modelfile-only`).
    #[serde(default)]
    pub modelfile_out: String,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct RuntimeResult {
    pub target: Target,
    /// `true` only when a tool was started and succeeded.
    pub ran: bool,
    /// The exact Modelfile (Ollama).
    pub modelfile: Option<String>,
    /// The commands that ran, or would run for a preview.
    pub commands: Vec<String>,
    /// The tool that was found (or `None`, see `tool_error`).
    pub tool: Option<String>,
    pub tool_error: Option<String>,
    /// Where the Modelfile was written (`modelfile_out`).
    pub written: Option<String>,
    /// The tool's own output (Ollama).
    pub output: String,
    /// LM Studio: the `modelKey` to `lms load`.
    pub key: Option<String>,
    /// What to tell the user, the line the CLI prints.
    pub summary: String,
}

fn name_ok(name: &str) -> Result<(), String> {
    let ok = !name.is_empty()
        && !name.starts_with(['-', '/', '.'])
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "._:/-".contains(c));
    if ok {
        Ok(())
    } else {
        Err(format!(
            "'{name}' is not a usable model name: use letters, digits and . _ : / - only, not starting with - . or /"
        ))
    }
}

/// Validate the form: paths through the path guard, names as the tools accept them.
fn checked(p: &RuntimeParams) -> Result<(std::path::PathBuf, Option<String>, String), String> {
    let model = checked_path("model path", &p.model_path, true)?;
    let bin = Some(p.bin.trim().to_string()).filter(|b| !b.is_empty());
    if let Some(b) = &bin {
        checked_path("tool path", b, true)?;
    }
    match p.target {
        Target::Ollama => {
            name_ok(p.name.trim())?;
            if !p.modelfile_out.trim().is_empty() {
                checked_path("Modelfile output path", p.modelfile_out.trim(), false)?;
            }
            Ok((model, bin, p.name.trim().to_string()))
        }
        Target::Lmstudio => {
            let repo = match p.repo.trim() {
                "" => rx::default_lmstudio_repo(&model),
                r => r.to_string(),
            };
            if repo.starts_with('-') {
                return Err(format!("'{repo}' is not a usable repo name"));
            }
            Ok((model, bin, repo))
        }
    }
}

fn base(p: &RuntimeParams) -> RuntimeResult {
    RuntimeResult {
        target: p.target,
        ran: false,
        modelfile: None,
        commands: Vec::new(),
        tool: None,
        tool_error: None,
        written: None,
        output: String::new(),
        key: None,
        summary: String::new(),
    }
}

/// What would run, without running it. Reads the model header and looks the tool up.
pub(crate) fn do_preview(p: &RuntimeParams) -> Result<RuntimeResult, String> {
    let (model, bin, name) = checked(p)?;
    let pv = match p.target {
        Target::Ollama => rx::ollama_preview(&model, &name, bin.as_deref())?,
        Target::Lmstudio => rx::lmstudio_preview(&model, &name, bin.as_deref())?,
    };
    let mut r = base(p);
    r.modelfile = pv.modelfile;
    r.commands = pv.commands;
    match pv.tool {
        Ok(t) => r.tool = Some(t.to_string_lossy().into_owned()),
        Err(e) => r.tool_error = Some(e),
    }
    r.summary = "nothing was run".into();
    Ok(r)
}

/// The testable core of [`export_to_runtime`]: the real export, or the Modelfile only.
pub(crate) fn do_export(
    p: &RuntimeParams,
    cancelled: &dyn Fn() -> bool,
) -> Result<RuntimeResult, String> {
    let (model, bin, name) = checked(p)?;
    let mut r = base(p);
    match p.target {
        Target::Ollama if !p.modelfile_out.trim().is_empty() => {
            let out = p.modelfile_out.trim();
            let text = rx::write_modelfile(&model, Path::new(out))?;
            r.commands = vec![format!("ollama create {name} -f \"{out}\"")];
            r.modelfile = Some(text);
            r.written = Some(out.to_string());
            r.summary = format!("wrote {out}; nothing was run");
        }
        Target::Ollama => {
            let run = rx::ollama_run(&model, &name, bin.as_deref(), cancelled)?;
            r.ran = true;
            r.modelfile = Some(run.modelfile);
            r.commands = vec![run.command];
            r.output = run.output;
            r.summary = format!("exported to Ollama as '{name}'  (try: ollama run {name})");
        }
        Target::Lmstudio => {
            let run = rx::lmstudio_run(&model, &name, bin.as_deref(), cancelled)?;
            r.ran = true;
            r.summary = format!(
                "imported into LM Studio as modelKey '{}'  (try: lms load {})",
                run.key, run.key
            );
            r.commands = run.commands;
            r.key = Some(run.key);
        }
    }
    Ok(r)
}

/// Show the Modelfile and the command(s) an export would use. Starts nothing.
#[tauri::command]
pub async fn preview_runtime_export(params: RuntimeParams) -> Result<RuntimeResult, String> {
    tauri::async_runtime::spawn_blocking(move || do_preview(&params))
        .await
        .map_err(|e| format!("task error: {e}"))?
}

/// Run `export-ollama` / `export-lmstudio` (or write the Modelfile only). One at a time;
/// `cancel_job("runtime_export")` is honoured before a tool starts and while LM Studio's
/// listing is awaited, but not inside a running `ollama create`.
#[tauri::command]
pub async fn export_to_runtime(
    state: State<'_, AppState>,
    params: RuntimeParams,
) -> Result<RuntimeResult, String> {
    let job = state.jobs.start(Job::RuntimeExport)?;
    tauri::async_runtime::spawn_blocking(move || do_export(&params, &|| job.cancelled()))
        .await
        .map_err(|e| format!("task error: {e}"))?
}

